const fs = require('fs');
const item = $input.first().json;

const linkedinPrompt = fs.readFileSync('/prompts/linkedin.md', 'utf8')
  .replace('{{title}}', item.title).replace('{{summary}}', item.summary)
  .replace('{{key_points}}', JSON.stringify(item.key_points))
  .replace('{{category}}', item.category).replace('{{newsletter_url}}', item.newsletter_url || '');

const tweetPrompt = fs.readFileSync('/prompts/tweet.md', 'utf8')
  .replace('{{title}}', item.title).replace('{{summary}}', item.summary)
  .replace('{{key_points}}', JSON.stringify(item.key_points))
  .replace('{{article_url}}', item.url).replace('{{newsletter_url}}', item.newsletter_url || '');

const threadsPrompt = fs.readFileSync('/prompts/threads.md', 'utf8')
  .replace('{{title}}', item.title).replace('{{summary}}', item.summary)
  .replace('{{article_url}}', item.url).replace('{{newsletter_url}}', item.newsletter_url || '');

return [{ json: { ...item, linkedinPrompt, tweetPrompt, threadsPrompt } }];
